import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.C0KMm31j.js";const d="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_01_boundary.png",r="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_02_lifecycle.png",i="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_04_feedback.png",l="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_05_eta_constraints.png",n="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_03_timer_pipeline.png",s="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_06_dynamic_boundaries.png",f=JSON.parse('{"title":"控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother","description":"Controller Server 给出的 cmdvel 往往每个控制周期跳变一次：这一拍需要直行，下一拍可能急转，再下一拍又要求停车。底盘若原样执行，速度阶跃会放大机械冲击、电流峰值和轮胎打滑。","frontmatter":{"title":"控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother","description":"Controller Server 给出的 cmdvel 往往每个控制周期跳变一次：这一拍需要直行，下一拍可能急转，再下一拍又要求停车。底盘若原样执行，速度阶跃会放大机械冲击、电流峰值和轮胎打滑。","date":"2026-07-24","topic":"Nav2 工程实践","section":"五 · 平滑器与基础工具","readingTime":15,"source":"2026-07-24/nav2_velocity_smoother_source_walkthrough.md","status":"published","cover":"/article-assets/2026-07-24/nav2_velocity_smoother_source_01_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-velocity-smoother-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother"}],["meta",{"property":"og:description","content":"Controller Server 给出的 cmdvel 往往每个控制周期跳变一次：这一拍需要直行，下一拍可能急转，再下一拍又要求停车。底盘若原样执行，速度阶跃会放大机械冲击、电流峰值和轮胎打滑。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-velocity-smoother-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_01_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-24"}],["meta",{"name":"twitter:title","content":"控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother"}],["meta",{"name":"twitter:description","content":"Controller Server 给出的 cmdvel 往往每个控制周期跳变一次：这一拍需要直行，下一拍可能急转，再下一拍又要求停车。底盘若原样执行，速度阶跃会放大机械冲击、电流峰值和轮胎打滑。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_velocity_smoother_source_01_boundary.png"}]],"prev":{"text":"规划、控制、恢复都在借谁的手？逐函数拆解 Nav2 公共底座 nav2_util","link":"/nav2/nav2-util-source-walkthrough"},"next":{"text":"Nav2 的规划、控制、恢复为何都离不开它？逐函数拆解 nav2_util 的 128 个公共入口","link":"/nav2/nav2-util-128-functions-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-velocity-smoother-source-walkthrough.md","filePath":"nav2/nav2-velocity-smoother-source-walkthrough.md","lastUpdated":null}'),h={name:"nav2/nav2-velocity-smoother-source-walkthrough.md"};function m(p,e,_,u,b,v){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="控制器只发-20-hz-底盘为何还能更丝滑-逐函数拆解-nav2-velocity-smoother" tabindex="-1">控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother <a class="header-anchor" href="#控制器只发-20-hz-底盘为何还能更丝滑-逐函数拆解-nav2-velocity-smoother" aria-label="Permalink to &quot;控制器只发 20 Hz，底盘为何还能更丝滑？逐函数拆解 Nav2 Velocity Smoother&quot;">​</a></h1><p>Controller Server 给出的 <code>cmd_vel</code> 往往每个控制周期跳变一次：这一拍需要直行，下一拍可能急转，再下一拍又要求停车。底盘若原样执行，速度阶跃会放大机械冲击、电流峰值和轮胎打滑。</p><p><code>nav2_velocity_smoother</code> 位于控制器与底盘之间。它不重新规划轨迹，也不判断障碍物，而是以独立频率持续逼近期望速度，把三轴速度限制、加速度、减速度、死区和命令超时统一变成最终 Twist。</p><p>本文以当前工程中的 <code>nav2_velocity_smoother 1.1.20</code> 为准，覆盖 <code>VelocitySmoother</code> 的 12 个生产函数与独立进程 <code>main()</code>，合计 13 个生产函数。测试函数和组件注册宏不计入函数数量；<code>nav2_util::OdomSmoother</code>、Lifecycle、Bond、rclcpp Timer 等包外调用只解释接口与数据流，不展开其他包源码。</p><p><img src="'+d+'" alt="nav2_velocity_smoother 包边界与总数据流"></p><h2 id="一、包边界-它整形速度-不替控制器做决策" tabindex="-1">一、包边界：它整形速度，不替控制器做决策 <a class="header-anchor" href="#一、包边界-它整形速度-不替控制器做决策" aria-label="Permalink to &quot;一、包边界：它整形速度，不替控制器做决策&quot;">​</a></h2><h3 id="_1-1-输入-topic-与真实工程重映射" tabindex="-1">1.1 输入 Topic 与真实工程重映射 <a class="header-anchor" href="#_1-1-输入-topic-与真实工程重映射" aria-label="Permalink to &quot;1.1 输入 Topic 与真实工程重映射&quot;">​</a></h3><p>源码创建普通 <code>geometry_msgs::msg::Twist</code> 订阅，Topic 相对名为 <code>cmd_vel</code>，QoS depth 为 1。输入通常来自包外 Controller Server。</p><p>当前 <code>myagv_test_bringup</code> 与 <code>nav2_regulated_modules</code> 的 Launch 都把输入重映射成 <code>cmd_vel_nav</code>。因此源码中的 <code>cmd_vel</code> 是接口默认名，运行图里的实际名称由 Launch 决定。</p><p>CLOSED_LOOP 模式还会间接消费 Odometry。订阅并不在本包中手写，而是由包外 <code>nav2_util::OdomSmoother</code> 根据 <code>odom_topic</code> 创建并维护。</p><h3 id="_1-2-输出-topic-与下游" tabindex="-1">1.2 输出 Topic 与下游 <a class="header-anchor" href="#_1-2-输出-topic-与下游" aria-label="Permalink to &quot;1.2 输出 Topic 与下游&quot;">​</a></h3><p>源码创建 Lifecycle Publisher，默认相对名为 <code>cmd_vel_smoothed</code>，消息仍是 Twist。当前两套本地 Bringup 把它重映射为 <code>cmd_vel</code>，交给底盘桥接、<code>controlpub</code> 或其他包外执行链。</p><p>本包只写 <code>linear.x</code>、<code>linear.y</code> 与 <code>angular.z</code>。Twist 的 <code>linear.z</code>、<code>angular.x</code> 和 <code>angular.y</code> 保持默认零，不参与平滑。</p><h3 id="_1-3-生命周期与参数输入" tabindex="-1">1.3 生命周期与参数输入 <a class="header-anchor" href="#_1-3-生命周期与参数输入" aria-label="Permalink to &quot;1.3 生命周期与参数输入&quot;">​</a></h3><p>节点由包外 Lifecycle Manager 执行 configure、activate、deactivate、cleanup 和 shutdown。ACTIVE 后建立 Bond，让 Lifecycle Manager 可以监测进程心跳。</p><p>运行期还接收参数批次。参数控制频率、反馈模式、三轴速度、加减速度、死区、Odometry 时间窗和命令超时。</p><h2 id="二、velocitysmoother-与析构-最小构造-延迟配置" tabindex="-1">二、VelocitySmoother() 与析构：最小构造，延迟配置 <a class="header-anchor" href="#二、velocitysmoother-与析构-最小构造-延迟配置" aria-label="Permalink to &quot;二、VelocitySmoother() 与析构：最小构造，延迟配置&quot;">​</a></h2><h3 id="_2-1-velocitysmoother-初始化节点和时间类型" tabindex="-1">2.1 VelocitySmoother() 初始化节点和时间类型 <a class="header-anchor" href="#_2-1-velocitysmoother-初始化节点和时间类型" aria-label="Permalink to &quot;2.1 VelocitySmoother() 初始化节点和时间类型&quot;">​</a></h3><p><code>VelocitySmoother()</code> 调用包外 <code>nav2_util::LifecycleNode(&quot;velocity_smoother&quot;, &quot;&quot;, options)</code>，并用节点 Clock 类型构造零值 <code>last_command_time_</code>。</p><p>构造函数不声明参数、不创建 Topic，也不启动 Timer。所有可能失败的配置都推迟到 <code>on_configure()</code>，符合 Lifecycle 的资源管理方式。</p><p>它只记录创建日志。独立进程中的 <code>SpdlogWrapper::init()</code> 不在构造函数里调用，因此 Component 模式不会由本类重复初始化全局日志包装器。</p><h3 id="_2-2-velocitysmoother-兜底取消-timer" tabindex="-1">2.2 ~VelocitySmoother() 兜底取消 Timer <a class="header-anchor" href="#_2-2-velocitysmoother-兜底取消-timer" aria-label="Permalink to &quot;2.2 ~VelocitySmoother() 兜底取消 Timer&quot;">​</a></h3><p><code>~VelocitySmoother()</code> 检查 <code>timer_</code>，存在时 cancel 并 reset。正常 Lifecycle 路径应在 deactivate 阶段已经完成这件事，析构只提供退出兜底。</p><p>析构函数不发布零速度。进程异常结束时能否让底盘停车，还依赖下游命令看门狗和整车安全链，不能只依赖本节点析构。</p><h2 id="三、on-configure-参数、校验与通信对象一次建立" tabindex="-1">三、on_configure()：参数、校验与通信对象一次建立 <a class="header-anchor" href="#三、on-configure-参数、校验与通信对象一次建立" aria-label="Permalink to &quot;三、on_configure()：参数、校验与通信对象一次建立&quot;">​</a></h2><p><img src="'+r+'" alt="Velocity Smoother Lifecycle 与资源生命周期"></p><h3 id="_3-1-平滑元数据" tabindex="-1">3.1 平滑元数据 <a class="header-anchor" href="#_3-1-平滑元数据" aria-label="Permalink to &quot;3.1 平滑元数据&quot;">​</a></h3><p><code>on_configure()</code> 通过包外 <code>declare_parameter_if_not_declared()</code> 声明并读取：</p><ul><li><code>smoothing_frequency</code>：Timer 目标频率，默认 20 Hz。</li><li><code>feedback</code>：<code>OPEN_LOOP</code> 或 <code>CLOSED_LOOP</code>。</li><li><code>scale_velocities</code>：是否用统一 η 比例缩放三轴速度差。</li></ul><p>回调输入的 Lifecycle State 没有参与逻辑。成功输出是 <code>CallbackReturn::SUCCESS</code>；无效配置主要通过抛出 <code>std::runtime_error</code> 让 configure 失败。</p><h3 id="_3-2-三轴运动学参数" tabindex="-1">3.2 三轴运动学参数 <a class="header-anchor" href="#_3-2-三轴运动学参数" aria-label="Permalink to &quot;3.2 三轴运动学参数&quot;">​</a></h3><p><code>max_velocity</code>、<code>min_velocity</code>、<code>max_accel</code>、<code>max_decel</code> 都按 x、y、theta 排列。默认 y 轴上下限为零，对应差速底盘；全向底盘可以配置非零 y。</p><p>源码要求 <code>max_accel</code> 非负、<code>max_decel</code> 非正，并要求每个轴 <code>min_velocity&lt;=max_velocity</code>。这些符号直接参与单周期速度变化窗口，减速度若误写成正数会破坏公式。</p><p>当前校验顺序有一个重要边界：函数先用下标访问数组前三项做符号与大小比较，随后才统一检查五个数组的 size 是否等于 3。长度不足时，size 错误还没被抛出，就已经存在越界访问风险。</p><h3 id="_3-3-odometry、死区与超时" tabindex="-1">3.3 Odometry、死区与超时 <a class="header-anchor" href="#_3-3-odometry、死区与超时" aria-label="Permalink to &quot;3.3 Odometry、死区与超时&quot;">​</a></h3><p>函数读取 <code>odom_topic</code>、<code>odom_duration</code>、<code>deadband_velocity</code> 和 <code>velocity_timeout</code>。timeout 从 double 秒转换成 <code>rclcpp::Duration</code>。</p><p>deadband 同样必须是三项，但 configure 只检查长度，不检查是否非负。负死区会让 <code>fabs(v)&lt;deadband</code> 永远为 false，等于静默关闭该轴死区。</p><h3 id="_3-4-open-loop-与-closed-loop-初始化" tabindex="-1">3.4 OPEN_LOOP 与 CLOSED_LOOP 初始化 <a class="header-anchor" href="#_3-4-open-loop-与-closed-loop-初始化" aria-label="Permalink to &quot;3.4 OPEN_LOOP 与 CLOSED_LOOP 初始化&quot;">​</a></h3><p>feedback 为 <code>OPEN_LOOP</code> 时只设置 <code>open_loop_=true</code>。feedback 为 <code>CLOSED_LOOP</code> 时设置 false，并创建包外 <code>nav2_util::OdomSmoother(node, odom_duration, odom_topic)</code>。</p><p>字符串不匹配两个合法值就抛异常。比较区分大小写，<code>open_loop</code> 或 <code>Closed_Loop</code> 都不会被接受。</p><h3 id="_3-5-创建-publisher-与-subscription" tabindex="-1">3.5 创建 Publisher 与 Subscription <a class="header-anchor" href="#_3-5-创建-publisher-与-subscription" aria-label="Permalink to &quot;3.5 创建 Publisher 与 Subscription&quot;">​</a></h3><p><code>on_configure()</code> 创建 <code>cmd_vel_smoothed</code> Lifecycle Publisher 和 <code>cmd_vel</code> Subscription。输入订阅是普通 rclcpp Subscription，不会因为节点 INACTIVE 自动停收消息。</p><p>因此节点 configure 后即使尚未 activate，<code>inputCommandCallback()</code> 仍可能更新 <code>command_</code> 与 <code>last_command_time_</code>。activate 只决定 Timer 和 Lifecycle Publisher 是否工作。</p><h2 id="四、lifecycle-激活、停用与清理" tabindex="-1">四、Lifecycle 激活、停用与清理 <a class="header-anchor" href="#四、lifecycle-激活、停用与清理" aria-label="Permalink to &quot;四、Lifecycle 激活、停用与清理&quot;">​</a></h2><h3 id="_4-1-on-activate-启动周期执行" tabindex="-1">4.1 on_activate() 启动周期执行 <a class="header-anchor" href="#_4-1-on-activate-启动周期执行" aria-label="Permalink to &quot;4.1 on_activate() 启动周期执行&quot;">​</a></h3><p><code>on_activate()</code> 激活 <code>smoothed_cmd_pub_</code>，用 <code>1000/smoothing_frequency</code> 计算毫秒周期，转成 int 后创建 Wall Timer，回调绑定 <code>smootherTimer()</code>。</p><p>它随后注册 <code>dynamicParametersCallback()</code>，再调用 LifecycleNode 的包外 <code>createBond()</code>。成功输出固定为 SUCCESS。</p><p>毫秒整数转换会截断小数。例如 30 Hz 变成 33 ms，实际约 30.3 Hz；频率超过 1000 Hz 时周期可能截成 0 ms。源码没有验证 frequency 必须大于零，也没有设置最小 Timer 周期。</p><h3 id="_4-2-on-deactivate-停止输出和热更新" tabindex="-1">4.2 on_deactivate() 停止输出和热更新 <a class="header-anchor" href="#_4-2-on-deactivate-停止输出和热更新" aria-label="Permalink to &quot;4.2 on_deactivate() 停止输出和热更新&quot;">​</a></h3><p><code>on_deactivate()</code> cancel 并 reset Timer，停用 Lifecycle Publisher，reset 动态参数回调句柄，再调用包外 <code>destroyBond()</code>。</p><p>Subscription 没有销毁，所以 INACTIVE 阶段仍能缓存新命令。动态参数回调已经注销，此时参数存储可能改变，但 C++ 成员不会同步；单纯再次 activate 也不会重新读参数。</p><h3 id="_4-3-on-cleanup-释放-configure-资源" tabindex="-1">4.3 on_cleanup() 释放 configure 资源 <a class="header-anchor" href="#_4-3-on-cleanup-释放-configure-资源" aria-label="Permalink to &quot;4.3 on_cleanup() 释放 configure 资源&quot;">​</a></h3><p><code>on_cleanup()</code> reset Publisher、OdomSmoother 与 Subscription，返回 SUCCESS。按照合法 Lifecycle 顺序，Timer 和参数回调应已由 deactivate 清理。</p><p>函数没有显式清空 <code>command_</code>、<code>last_cmd_</code>、<code>stopped_</code> 或 <code>last_command_time_</code>。同一对象重新 configure 后，旧命令状态仍可能保留，直到新命令到达或 timeout 路径处理。</p><h3 id="_4-4-on-shutdown-只记录状态" tabindex="-1">4.4 on_shutdown() 只记录状态 <a class="header-anchor" href="#_4-4-on-shutdown-只记录状态" aria-label="Permalink to &quot;4.4 on_shutdown() 只记录状态&quot;">​</a></h3><p><code>on_shutdown()</code> 只输出日志并返回 SUCCESS，不发布零速度，也不主动释放资源。正常 shutdown transition 之前通常已经经过 deactivate 与 cleanup。</p><h2 id="五、inputcommandcallback-只缓存目标-不在回调里平滑" tabindex="-1">五、inputCommandCallback()：只缓存目标，不在回调里平滑 <a class="header-anchor" href="#五、inputcommandcallback-只缓存目标-不在回调里平滑" aria-label="Permalink to &quot;五、inputCommandCallback()：只缓存目标，不在回调里平滑&quot;">​</a></h2><h3 id="_5-1-拒绝-nan-与-inf" tabindex="-1">5.1 拒绝 NaN 与 Inf <a class="header-anchor" href="#_5-1-拒绝-nan-与-inf" aria-label="Permalink to &quot;5.1 拒绝 NaN 与 Inf&quot;">​</a></h3><p><code>inputCommandCallback()</code> 接收 Twist shared pointer，先调用包外 <code>nav2_util::validateTwist()</code>。任一分量包含 NaN 或 Inf 时记录错误并返回。</p><p>无效消息不会覆盖上一条合法 <code>command_</code>，也不会刷新 <code>last_command_time_</code>。如果上游持续发送无效值，旧合法命令最终仍会按 velocity timeout 进入停车流程。</p><h3 id="_5-2-保存指针和接收时间" tabindex="-1">5.2 保存指针和接收时间 <a class="header-anchor" href="#_5-2-保存指针和接收时间" aria-label="Permalink to &quot;5.2 保存指针和接收时间&quot;">​</a></h3><p>合法输入直接赋给 <code>command_</code>，并用节点 <code>now()</code> 更新 <code>last_command_time_</code>。函数不复制 Twist、不做限速，也不立即发布。</p><p>这种设计把“上游消息到达频率”和“下游平滑发布频率”解耦。Controller 可能 20 Hz 更新目标，Smoother 可以用更高频 Timer 在两个目标之间逐步逼近。</p><h3 id="_5-3-qos-depth-1-的语义" tabindex="-1">5.3 QoS depth=1 的语义 <a class="header-anchor" href="#_5-3-qos-depth-1-的语义" aria-label="Permalink to &quot;5.3 QoS depth=1 的语义&quot;">​</a></h3><p>输入队列只保留很浅的最新数据，适合速度控制：处理积压旧命令没有意义。真正每周期使用的是成员 <code>command_</code> 中最近一次已经执行回调的目标。</p><h2 id="六、open-loop-与-closed-loop-当前速度从哪里来" tabindex="-1">六、OPEN_LOOP 与 CLOSED_LOOP：当前速度从哪里来 <a class="header-anchor" href="#六、open-loop-与-closed-loop-当前速度从哪里来" aria-label="Permalink to &quot;六、OPEN_LOOP 与 CLOSED_LOOP：当前速度从哪里来&quot;">​</a></h2><p><img src="'+i+'" alt="OPEN_LOOP 与 CLOSED_LOOP 当前速度来源"></p><h3 id="_6-1-open-loop-使用-last-cmd" tabindex="-1">6.1 OPEN_LOOP 使用 last_cmd_ <a class="header-anchor" href="#_6-1-open-loop-使用-last-cmd" aria-label="Permalink to &quot;6.1 OPEN_LOOP 使用 last_cmd_&quot;">​</a></h3><p>OPEN_LOOP 把上一周期内部计算的 <code>last_cmd_</code> 当作当前速度。它假设底盘能够及时跟随上一条平滑输出。</p><p>优点是不受 Odometry 频率、噪声和延迟影响；代价是轮胎打滑、急停、底盘饱和或通信丢包不会反馈到平滑器。</p><h3 id="_6-2-closed-loop-使用-odomsmoother" tabindex="-1">6.2 CLOSED_LOOP 使用 OdomSmoother <a class="header-anchor" href="#_6-2-closed-loop-使用-odomsmoother" aria-label="Permalink to &quot;6.2 CLOSED_LOOP 使用 OdomSmoother&quot;">​</a></h3><p>CLOSED_LOOP 调用包外 <code>odom_smoother_-&gt;getTwist()</code>。OdomSmoother 通常订阅 <code>odom_topic</code>，对 <code>odom_duration</code> 时间窗中的 Twist 做平滑，再返回机器人实测当前速度。</p><p>本包不使用 Odometry Pose、协方差或 TF。它只需要速度反馈作为下一周期约束起点。</p><h3 id="_6-3-反馈频率与窗口的取舍" tabindex="-1">6.3 反馈频率与窗口的取舍 <a class="header-anchor" href="#_6-3-反馈频率与窗口的取舍" aria-label="Permalink to &quot;6.3 反馈频率与窗口的取舍&quot;">​</a></h3><p>如果 smoothing frequency 明显高于 Odometry 更新频率，多个 Timer 周期会重复看到同一份或滞后的速度；窗口过长又会增加相位延迟。结果可能是响应变慢甚至振荡。</p><p>当前本地 <code>myagv_test_bringup</code> 与 <code>nav2_regulated_modules</code> 都配置 <code>feedback=OPEN_LOOP</code>、<code>odom_topic=/odometry</code>、<code>odom_duration=0.1</code>。此时 Odom 参数已存在，但 configure 阶段不会创建 OdomSmoother。</p><h2 id="七、findetaconstraint-找出三轴最严格的比例" tabindex="-1">七、findEtaConstraint()：找出三轴最严格的比例 <a class="header-anchor" href="#七、findetaconstraint-找出三轴最严格的比例" aria-label="Permalink to &quot;七、findEtaConstraint()：找出三轴最严格的比例&quot;">​</a></h2><p><img src="'+l+'" alt="三轴 η 比例缩放与单周期加减速度约束"></p><h3 id="_7-1-加速与减速如何分类" tabindex="-1">7.1 加速与减速如何分类 <a class="header-anchor" href="#_7-1-加速与减速如何分类" aria-label="Permalink to &quot;7.1 加速与减速如何分类&quot;">​</a></h3><p><code>findEtaConstraint()</code> 输入当前速度、目标速度、最大加速度和最大减速度，计算 <code>dv=v_cmd-v_curr</code>。</p><p>目标绝对值不小于当前绝对值并且两者同号时，函数视为加速，单周期允许变化范围是 <code>±accel/frequency</code>。其他情况视为减速，包括速度幅值下降和正负号反转，范围由负数 <code>decel/frequency</code> 构造。</p><p>换向不会直接从正速度跳到负速度，而是先按减速度穿过零，随后按加速度建立反向速度。</p><h3 id="_7-2-返回值-1-与正-η" tabindex="-1">7.2 返回值 -1 与正 η <a class="header-anchor" href="#_7-2-返回值-1-与正-η" aria-label="Permalink to &quot;7.2 返回值 -1 与正 η&quot;">​</a></h3><p>如果 dv 已在允许窗口内，函数返回 <code>-1.0</code>，表示该轴不需要比例缩放。</p><p>dv 超过上界时返回 <code>upper/dv</code>，低于下界时返回 <code>lower/dv</code>。正常参数下得到的正 η 不大于 1，代表这一周期只能完成目标速度差的一部分。</p><h3 id="_7-3-scale-velocities-如何选择-η" tabindex="-1">7.3 scale_velocities 如何选择 η <a class="header-anchor" href="#_7-3-scale-velocities-如何选择-η" aria-label="Permalink to &quot;7.3 scale_velocities 如何选择 η&quot;">​</a></h3><p><code>smootherTimer()</code> 对 x、y、theta 分别调用该函数，并选择与 1 差距最大的正 η。对 0～1 范围而言，这就是最小、最严格的比例。</p><p>三个速度差共用同一 η，可以尽量保持 <code>[dvx,dvy,dtheta]</code> 的方向。例如 x 轴受限到只能完成目标差的 30%，其他轴也按 30% 推进，而不是各自一步到位。</p><h2 id="八、applyconstraints-把比例变成单轴输出" tabindex="-1">八、applyConstraints()：把比例变成单轴输出 <a class="header-anchor" href="#八、applyconstraints-把比例变成单轴输出" aria-label="Permalink to &quot;八、applyConstraints()：把比例变成单轴输出&quot;">​</a></h2><h3 id="_8-1-输入输出公式" tabindex="-1">8.1 输入输出公式 <a class="header-anchor" href="#_8-1-输入输出公式" aria-label="Permalink to &quot;8.1 输入输出公式&quot;">​</a></h3><p><code>applyConstraints()</code> 使用与 <code>findEtaConstraint()</code> 相同的加速／减速分类，重新计算单周期上下界，返回：</p><p><code>v_next = v_curr + clamp(eta * dv, lower, upper)</code></p><p>即使统一 η 让某个轴出现特殊边界，最终 clamp 仍保证该轴不超过自己的加减速度范围。</p><h3 id="_8-2-scale-velocities-false-的行为" tabindex="-1">8.2 scale_velocities=false 的行为 <a class="header-anchor" href="#_8-2-scale-velocities-false-的行为" aria-label="Permalink to &quot;8.2 scale_velocities=false 的行为&quot;">​</a></h3><p>关闭比例缩放时，Timer 保持 <code>eta=1.0</code>。三个轴分别执行 clamp，各自以最大允许步长逼近目标。</p><p>这能更快利用每个轴能力，但目标速度变化向量的方向可能改变。是否需要保持方向取决于底盘类型和控制需求。</p><h3 id="_8-3-频率直接改变单周期步长" tabindex="-1">8.3 频率直接改变单周期步长 <a class="header-anchor" href="#_8-3-频率直接改变单周期步长" aria-label="Permalink to &quot;8.3 频率直接改变单周期步长&quot;">​</a></h3><p>加速度单位是每秒变化量，源码用它除以 smoothing frequency 得到每周期步长。频率越高，每次变化越小，但单位时间理论总变化量保持近似相同。</p><p>Timer 实际周期被整数毫秒截断，极端频率或调度抖动时，公式仍使用配置频率而不是实测 dt。因此它是固定步长离散器，不是按真实时间间隔积分。</p><h2 id="九、smoothertimer-一个周期内速度如何流动" tabindex="-1">九、smootherTimer()：一个周期内速度如何流动 <a class="header-anchor" href="#九、smoothertimer-一个周期内速度如何流动" aria-label="Permalink to &quot;九、smootherTimer()：一个周期内速度如何流动&quot;">​</a></h2><p><img src="'+n+'" alt="smootherTimer 单周期处理流水线"></p><h3 id="_9-1-没有命令就不发布" tabindex="-1">9.1 没有命令就不发布 <a class="header-anchor" href="#_9-1-没有命令就不发布" aria-label="Permalink to &quot;9.1 没有命令就不发布&quot;">​</a></h3><p><code>smootherTimer()</code> 检查 <code>command_</code>。尚未收到合法 Twist 时直接返回，不发布默认零速度。</p><p>这避免节点刚 activate 就抢占其他速度源，但也意味着下游必须有自己的“无消息停车”安全策略。</p><h3 id="_9-2-timeout-把目标改成零" tabindex="-1">9.2 timeout 把目标改成零 <a class="header-anchor" href="#_9-2-timeout-把目标改成零" aria-label="Permalink to &quot;9.2 timeout 把目标改成零&quot;">​</a></h3><p>函数用 ROS 时间比较 <code>now()-last_command_time_</code> 与 <code>velocity_timeout_</code>。超时且内部已经是零或 <code>stopped_</code> 为 true 时，本周期返回并保持停止。</p><p>超时但仍有速度时，它把 <code>*command_</code> 原地改成零 Twist，随后继续正常约束流程。输出不会瞬间跳零，而是按照 max_decel 多周期减速。</p><h3 id="_9-3-选择-current-并限制绝对速度" tabindex="-1">9.3 选择 current 并限制绝对速度 <a class="header-anchor" href="#_9-3-选择-current-并限制绝对速度" aria-label="Permalink to &quot;9.3 选择 current 并限制绝对速度&quot;">​</a></h3><p>OPEN_LOOP 取 <code>last_cmd_</code>，CLOSED_LOOP 取 OdomSmoother Twist。接着把 <code>command_</code> 的 x、y、theta 原地 clamp 到 min／max velocity。</p><p>原地修改意味着超限目标的信息会丢失。即使随后动态放宽 max velocity，在新上游命令到达前，成员里仍是之前被截断的目标。</p><h3 id="_9-4-η-与逐轴约束" tabindex="-1">9.4 η 与逐轴约束 <a class="header-anchor" href="#_9-4-η-与逐轴约束" aria-label="Permalink to &quot;9.4 η 与逐轴约束&quot;">​</a></h3><p>启用 scale velocities 时，函数计算三个 curr_eta 并选择最严格者。随后对 x、y、theta 分别调用 <code>applyConstraints()</code>，得到本周期输出。</p><p>计算结果先写入 <code>last_cmd_</code>，作为 OPEN_LOOP 下一周期 current。</p><h3 id="_9-5-deadband-与发布" tabindex="-1">9.5 deadband 与发布 <a class="header-anchor" href="#_9-5-deadband-与发布" aria-label="Permalink to &quot;9.5 deadband 与发布&quot;">​</a></h3><p>函数最后比较输出绝对值与 <code>deadband_velocity</code>，小于阈值的轴写成零，再通过 Lifecycle Publisher 发布。</p><p>关键顺序是 <code>last_cmd_</code> 在 deadband 之前保存。某轴计算为 0.05、死区为 0.1 时，实际发布零，但 OPEN_LOOP 内部仍认为上一周期速度是 0.05。内部状态和下游收到的 Twist 因此可能不同。</p><h2 id="十、超时停车与时钟边界" tabindex="-1">十、超时停车与时钟边界 <a class="header-anchor" href="#十、超时停车与时钟边界" aria-label="Permalink to &quot;十、超时停车与时钟边界&quot;">​</a></h2><h3 id="_10-1-渐进停车而非单帧急停" tabindex="-1">10.1 渐进停车而非单帧急停 <a class="header-anchor" href="#_10-1-渐进停车而非单帧急停" aria-label="Permalink to &quot;10.1 渐进停车而非单帧急停&quot;">​</a></h3><p>velocity timeout 的目的不是立即覆盖成零输出，而是把期望目标置零，再复用减速度约束。这样上游停止发布后，底盘仍能收到一串逐渐减小的速度。</p><p>当 <code>last_cmd_</code> 精确为默认零 Twist或 <code>stopped_</code> 已经置 true，Timer 不再持续发布零。下游若需要恒定零指令，必须自行配置命令看门狗。</p><h3 id="_10-2-wall-timer-与-ros-时间混用" tabindex="-1">10.2 Wall Timer 与 ROS 时间混用 <a class="header-anchor" href="#_10-2-wall-timer-与-ros-时间混用" aria-label="Permalink to &quot;10.2 Wall Timer 与 ROS 时间混用&quot;">​</a></h3><p>平滑周期由 Wall Timer 驱动，不受 <code>/clock</code> 暂停影响；timeout 判断使用节点 ROS 时间。<code>use_sim_time=true</code> 且仿真时钟停止时，Timer 仍运行，但旧命令的 ROS 时间年龄不再增长。</p><p>这可能让平滑器持续重复旧目标，而不是进入 timeout。仿真暂停是否应该冻结底盘取决于系统设计，实车配置通常应使用连续推进的系统时间。</p><h3 id="_10-3-pause-resume-的旧命令" tabindex="-1">10.3 pause／resume 的旧命令 <a class="header-anchor" href="#_10-3-pause-resume-的旧命令" aria-label="Permalink to &quot;10.3 pause／resume 的旧命令&quot;">​</a></h3><p>deactivate 会停止 Timer，却不清空 <code>command_</code> 和 <code>last_command_time_</code>。恢复 activate 后，如果旧命令已经超时，Timer 会沿减速度路径停车；如果 ROS 时间没有推进，旧命令可能继续被使用。</p><h2 id="十一、dynamicparameterscallback-热更新能力与副作用" tabindex="-1">十一、dynamicParametersCallback()：热更新能力与副作用 <a class="header-anchor" href="#十一、dynamicparameterscallback-热更新能力与副作用" aria-label="Permalink to &quot;十一、dynamicParametersCallback()：热更新能力与副作用&quot;">​</a></h2><p><img src="'+s+'" alt="动态参数热更新与当前实现边界"></p><h3 id="_11-1-double-参数" tabindex="-1">11.1 double 参数 <a class="header-anchor" href="#_11-1-double-参数" aria-label="Permalink to &quot;11.1 double 参数&quot;">​</a></h3><p><code>dynamicParametersCallback()</code> 初始设置 <code>result.successful=true</code>，逐个检查参数类型和名称。</p><p>更新 <code>smoothing_frequency</code> 时先写成员，取消旧 Timer，再以新频率立即创建 Timer。函数没有检查零、负数或过高频率。</p><p><code>velocity_timeout</code> 直接重建 ROS Duration。<code>odom_duration</code> 写成员后立即创建新的 OdomSmoother，即使当前是 OPEN_LOOP。</p><h3 id="_11-2-double-array-参数" tabindex="-1">11.2 double array 参数 <a class="header-anchor" href="#_11-2-double-array-参数" aria-label="Permalink to &quot;11.2 double array 参数&quot;">​</a></h3><p>任何 double array 的长度不等于 3 都会让整批返回失败，即使名称不是本包关心的参数。</p><p><code>max_velocity</code>、<code>min_velocity</code> 和 <code>deadband_velocity</code> 直接覆盖成员。动态路径没有重新检查 min&lt;=max，也不检查 deadband 非负。</p><p><code>max_accel</code> 出现负数或 <code>max_decel</code> 出现正数时会把 result 置为 false，但循环结束后仍把整个数组写入成员。ROS 参数事务可能被拒绝，运行时 C++ 成员却已经变成无效值。</p><h3 id="_11-3-string-参数" tabindex="-1">11.3 string 参数 <a class="header-anchor" href="#_11-3-string-参数" aria-label="Permalink to &quot;11.3 string 参数&quot;">​</a></h3><p><code>feedback=OPEN_LOOP</code> 设置开环并 reset OdomSmoother；<code>feedback=CLOSED_LOOP</code> 设置闭环并新建 OdomSmoother。其他字符串让结果失败并 break。</p><p>更新 <code>odom_topic</code> 会写入新名称并立即重建 OdomSmoother，同样不判断当前是否开环。</p><h3 id="_11-4-批量更新不是原子成员事务" tabindex="-1">11.4 批量更新不是原子成员事务 <a class="header-anchor" href="#_11-4-批量更新不是原子成员事务" aria-label="Permalink to &quot;11.4 批量更新不是原子成员事务&quot;">​</a></h3><p>回调按顺序产生副作用。如果频率已重建 Timer，后续数组又因长度错误失败，ROS 参数批次可能整体不提交，但 Timer 和成员不会自动回滚。</p><p>安全改进应先完整校验整个 parameters 批次，把候选值保存在局部变量中；全部合法后再一次性更新成员与外部资源。</p><h3 id="_11-5-lifecycle-有效期" tabindex="-1">11.5 Lifecycle 有效期 <a class="header-anchor" href="#_11-5-lifecycle-有效期" aria-label="Permalink to &quot;11.5 Lifecycle 有效期&quot;">​</a></h3><p>动态回调只在 ACTIVE 的 <code>on_activate()</code> 注册，在 deactivate 时注销。INACTIVE 阶段设置参数可能更新参数服务器存储，却不会更新运行时成员；再次 activate 只创建 Timer，不重新读取全部参数。</p><p>需要一致刷新时，应让节点经过 cleanup 和 configure，或修改实现使 activate 主动重新同步。</p><h2 id="十二、main-与-component-部署" tabindex="-1">十二、main() 与 Component 部署 <a class="header-anchor" href="#十二、main-与-component-部署" aria-label="Permalink to &quot;十二、main() 与 Component 部署&quot;">​</a></h2><h3 id="_12-1-main-的进程数据流" tabindex="-1">12.1 main() 的进程数据流 <a class="header-anchor" href="#_12-1-main-的进程数据流" aria-label="Permalink to &quot;12.1 main() 的进程数据流&quot;">​</a></h3><p><code>main()</code> 调用 <code>rclcpp::init()</code>，初始化 <code>SpdlogWrapper(&quot;nav2_velocity_smoother&quot;,&quot;velocity_smoother&quot;)</code>，创建 VelocitySmoother shared pointer，并 spin 其 Node Base Interface。</p><p>spin 返回后执行 <code>rclcpp::shutdown()</code> 和 <code>SpdlogWrapper::shutdown()</code>，最后返回零。独立进程只管理节点和日志生命周期，不参与平滑数学。</p><h3 id="_12-2-共享库和组件注册" tabindex="-1">12.2 共享库和组件注册 <a class="header-anchor" href="#_12-2-共享库和组件注册" aria-label="Permalink to &quot;12.2 共享库和组件注册&quot;">​</a></h3><p>CMake 生成 <code>velocity_smoother_core</code> 共享库与 <code>velocity_smoother</code> 可执行文件。<code>RCLCPP_COMPONENTS_REGISTER_NODE</code> 让同一个类也能由 ComponentManager 加载；宏不计入生产函数。</p><p>独立进程与组合部署使用相同 Topic、参数、Lifecycle 和 Timer 实现，差异主要在进程边界与执行器调度。</p><h2 id="十三、当前本地配置如何经过这套算法" tabindex="-1">十三、当前本地配置如何经过这套算法 <a class="header-anchor" href="#十三、当前本地配置如何经过这套算法" aria-label="Permalink to &quot;十三、当前本地配置如何经过这套算法&quot;">​</a></h2><h3 id="_13-1-当前三轴限制" tabindex="-1">13.1 当前三轴限制 <a class="header-anchor" href="#_13-1-当前三轴限制" aria-label="Permalink to &quot;13.1 当前三轴限制&quot;">​</a></h3><p><code>myagv_test_bringup</code> 与 <code>nav2_regulated_modules</code> 当前都使用：</p><ul><li>最大速度 <code>[0.26,0.0,1.0]</code>。</li><li>最小速度 <code>[-0.26,0.0,-1.0]</code>。</li><li>最大加速度 <code>[2.5,0.0,3.2]</code>。</li><li>最大减速度 <code>[-2.5,0.0,-3.2]</code>。</li><li>smoothing frequency 20 Hz。</li><li>deadband 全零。</li><li>velocity timeout 1 s。</li></ul><p>y 轴被固定为零，符合差速底盘。单个理想周期内 x 最大变化约 0.125 m/s，theta 最大变化约 0.16 rad/s。</p><h3 id="_13-2-当前反馈和-topic-链" tabindex="-1">13.2 当前反馈和 Topic 链 <a class="header-anchor" href="#_13-2-当前反馈和-topic-链" aria-label="Permalink to &quot;13.2 当前反馈和 Topic 链&quot;">​</a></h3><p>feedback 为 OPEN_LOOP，所以 current 取 <code>last_cmd_</code>，不创建 Odometry 反馈链。<code>cmd_vel_nav</code> 进入平滑器，输出重映射成最终 <code>cmd_vel</code>。</p><p><code>odom_topic=/odometry</code> 与 <code>odom_duration=0.1</code> 只有切到 CLOSED_LOOP 后才真正参与 Timer current 计算。</p><h3 id="_13-3-调参应沿数据流定位" tabindex="-1">13.3 调参应沿数据流定位 <a class="header-anchor" href="#_13-3-调参应沿数据流定位" aria-label="Permalink to &quot;13.3 调参应沿数据流定位&quot;">​</a></h3><p>绝对速度过高，先检查 max／min velocity；速度爬升或刹车过快，检查 accel／decel 与 frequency；多轴方向失真，评估 scale velocities；小命令导致电机嗡鸣，检查 deadband；上游停止后仍运动，检查 timeout、ROS Clock 和下游看门狗。</p><p>CLOSED_LOOP 响应迟缓或振荡，应同时核对 Odometry 频率、延迟、噪声与 odom duration，不能只增大加速度参数。</p><h2 id="十四、总结-平滑器不是低通滤波器-而是离散运动学限幅器" tabindex="-1">十四、总结：平滑器不是低通滤波器，而是离散运动学限幅器 <a class="header-anchor" href="#十四、总结-平滑器不是低通滤波器-而是离散运动学限幅器" aria-label="Permalink to &quot;十四、总结：平滑器不是低通滤波器，而是离散运动学限幅器&quot;">​</a></h2><p>这 13 个生产函数构成一条清晰链路：输入回调缓存最新目标，独立 Wall Timer 选择开环或闭环 current，绝对速度先 clamp，可选 η 保持三轴变化方向，逐轴加减速度限制生成下一帧，timeout 把目标切到零，deadband 决定最终发布。</p><p>它没有对历史 cmd_vel 做均值、卷积或传统低通滤波。真正的核心是“每个离散周期最多允许速度变化多少”，以及“当前速度来自上一帧输出还是 Odometry 时间窗”。</p><p>阅读和调试本包时，应始终区分四个量：上游原始 <code>command_</code>、反馈得到的 current、本周期约束后的 <code>last_cmd_</code>、deadband 处理后的实际发布 Twist。多数看似矛盾的现象，都来自把这四个量误认为同一个速度。</p>',166)])])}const q=o(h,[["render",m]]);export{f as __pageData,q as default};
